import com.sun.net.httpserver.HttpServer; import java.net.InetSocketAddress; import java.io.OutputStream; public class Main { public static void main(String[] args) throws Exception { HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0); server.createContext("/", exchange -> { String resposta = "MecaniQA API rodando no Docker!"; exchange.sendResponseHeaders(200, resposta.length()); OutputStream os = exchange.getResponseBody(); os.write(resposta.getBytes()); os.close(); }); server.start(); System.out.println("Servidor rodando na porta 8080"); } }